/*
 * A044799  Numbers n such that string 8,6 occurs in the base 10
 *          representation of n but not of n+1.
 * https://oeis.org/A044799
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = n-th positive integer whose decimal representation
 *            contains the substring "86" but the representation of a(n)+1
 *            does not. The sequence is generated by scanning natural numbers
 *            in order and selecting those that satisfy the property
 * Range:     u8 n <= 2, u16 n <= 39, u32 n <= 39, u64 n <= 39, u128 n <= 39,
 *            big any n
 * Helpers:   contains86
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/contains86.h"

static void ensure_cap(size_t needed)
{
    static size_t stand_cap = 0;
    static seq_t *stand_arr = NULL;

    if (needed <= stand_cap)
        return;

    size_t new_cap = stand_cap ? stand_cap : 8;
    while (new_cap < needed)
        new_cap *= 2;

    seq_t *tmp = stand_arr ? (seq_t*)realloc(stand_arr, new_cap * sizeof(seq_t))
                           : (seq_t*)malloc(new_cap * sizeof(seq_t));
    stand_arr = tmp;
    stand_cap = new_cap;

    /* assign back to static variables */
    stand_arr;  /* silence unused warning */
    stand_cap;  /* silence unused warning */
}

seq_t a(idx_t n)
{
    /* Static state: cache of found values, capacity, length, and
       the next integer to examine. */
    static seq_t *cache = NULL;
    static size_t cap = 0;
    static size_t len = 0;
    static seq_t next_candidate = (seq_t)1;

    if (n == 0)
        return (seq_t)0;  /* robust against calls with n==0 */

    /* Grow cache array as needed. */
    if (len < (size_t)n)
    {
        if (cache == NULL)
        {
            cap = 8;
            cache = (seq_t*)malloc(cap * sizeof(seq_t));
        }
        else if (len == cap)
        {
            cap *= 2;
            cache = (seq_t*)realloc(cache, cap * sizeof(seq_t));
        }

        /* Generate terms until we have at least n of them. */
        while (len < (size_t)n)
        {
            /* Find the next number that contains "86" but not in (number+1). */
            while (true)
            {
                if (contains86(next_candidate) && !contains86(next_candidate + (seq_t)1))
                    break;
                next_candidate++;
            }

            /* Store the found number. */
            cache[len++] = next_candidate;

            /* Advance to the next candidate for subsequent searches. */
            next_candidate++;
        }
    }

    /* Return the (n-1)-th index (0-based). */
    return cache[(size_t)n - 1];
}
